package main

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"io"
	"testing"
)

// Exact immutable policy bytes, compressed only to keep the invented raw
// protocol fixtures self-contained. This is policy, not collected evidence.
func residentEmbeddedPolicy(t *testing.T) []byte {
	t.Helper()
	compressed, err := base64.StdEncoding.DecodeString(residentPolicyFixtureGzip)
	if err != nil {
		t.Fatal(err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		t.Fatal(err)
	}
	data, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	if err = reader.Close(); err != nil {
		t.Fatal(err)
	}
	if residentTestHash(data) != residentPolicySHA {
		t.Fatal("embedded policy identity mismatch")
	}
	return data
}

const residentPolicyFixtureGzip = ``
